import Foundation
import XCTest
@testable import RecordWire

/// Loads the vectors generated by the Rust side (`rightkit-record` macos::golden).
private func loadGolden() throws -> [String: Any] {
    let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("golden.json")
    let data = try Data(contentsOf: url)
    return try XCTUnwrap(try JSONSerialization.jsonObject(with: data) as? [String: Any])
}

private func same(_ a: [String: Any], _ b: [String: Any], file: StaticString = #filePath, line: UInt = #line) {
    XCTAssertTrue(NSDictionary(dictionary: a).isEqual(to: b), "\n\(a)\n  !=\n\(b)", file: file, line: line)
}

/// The sample the Rust test builds: raw hash is blake3 of the index as 8 little-endian bytes.
private func sample(_ index: UInt64, _ hostNs: UInt64, _ pts: UInt64) -> FrameSample {
    var le = index.littleEndian
    let hash = withUnsafeBytes(of: &le) { Blake3.text(Data($0)) }
    return FrameSample(index: index, hostNs: hostNs, samplePtsNs: pts, rawHash: hash)
}

final class GoldenTests: XCTestCase {
    func testBlake3MatchesTheRustCrate() throws {
        let golden = try loadGolden()
        let vectors = try XCTUnwrap(golden["blake3"] as? [[String: Any]])
        XCTAssertGreaterThan(vectors.count, 20)
        for vector in vectors {
            let len = try XCTUnwrap(vector["len"] as? Int)
            let want = try XCTUnwrap(vector["hash"] as? String)
            let input = Data((0..<len).map { UInt8($0 % 251) })
            XCTAssertEqual(Blake3.text(input), want, "length \(len)")
        }
    }

    func testBlake3OfNothingIsTheReferenceDigest() {
        XCTAssertEqual(Blake3.text(Data()), "blake3:af1349b9f5f9a1a6a0404dea36dcc9499bcb25c9adc112b7cc9a93cae41f3262")
    }

    func testFramingMatchesRustBytes() throws {
        let golden = try loadGolden()
        let bye = try XCTUnwrap(golden["framedBye"] as? [String: Any])
        let hex = try XCTUnwrap(bye["hex"] as? String)
        var bytes = Data()
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            bytes.append(UInt8(hex[index..<next], radix: 16)!)
            index = next
        }
        XCTAssertEqual(try Framing.encode(Messages.bye), bytes)
        let bodies = try Framing.bodies(of: bytes)
        XCTAssertEqual(bodies.count, 1)
        same(try Framing.parse(bodies[0]), try XCTUnwrap(bye["body"] as? [String: Any]))
    }

    func testEveryRequestTheCoreSendsDecodes() throws {
        let golden = try loadGolden()
        for scenario in try XCTUnwrap(golden["scenarios"] as? [[String: Any]]) {
            for frame in try XCTUnwrap(scenario["requests"] as? [[String: Any]]) {
                let request = try Request.decode(frame)
                XCTAssertEqual(request.id, (frame["id"] as? NSNumber)?.uint64Value)
                XCTAssertEqual(request.op, frame["op"] as? String)
                if request.op == "start" {
                    let plan = try StartPlan.decode(try XCTUnwrap(request.plan))
                    // Decoding then encoding the plan reproduces the core's JSON.
                    same(plan.json, try XCTUnwrap(frame["plan"] as? [String: Any]))
                }
            }
        }
    }

    func testPlanFieldsAreTheOnesTheCoreSent() throws {
        let golden = try loadGolden()
        let scenarios = try XCTUnwrap(golden["scenarios"] as? [[String: Any]])
        let requests = try XCTUnwrap(scenarios[0]["requests"] as? [[String: Any]])
        let plan = try StartPlan.decode(try XCTUnwrap(requests[2]["plan"] as? [String: Any]))
        XCTAssertEqual(plan.windowId, 4242)
        XCTAssertEqual(plan.pid, 77)
        XCTAssertEqual(plan.fps, 30)
        XCTAssertEqual(plan.scale, 2.0)
        XCTAssertEqual(plan.codec, .hevc)
        XCTAssertEqual(plan.visibility, .offScreenVisible)
        XCTAssertEqual(plan.masking, .declared([Rect(x: 1, y: 2, width: 30.5, height: 40)]))
        let other = try XCTUnwrap(scenarios[1]["requests"] as? [[String: Any]])
        XCTAssertEqual(try StartPlan.decode(try XCTUnwrap(other[1]["plan"] as? [String: Any])).masking, .captureSafeState)
        let unknown = try StartPlan.decode(try XCTUnwrap(golden["unknownMaskPlan"] as? [String: Any]))
        XCTAssertEqual(unknown.masking, .unknown)
    }

    func testHelperFramesMatchTheRustServer() throws {
        let golden = try loadGolden()
        let scenarios = try XCTUnwrap(golden["scenarios"] as? [[String: Any]])

        // full_take
        let host: UInt64 = 9_007_199_254_740_993
        let events: [HelperEvent] = [
            .ready(sample(0, host, 0)),
            .frame(sample(1, host + 33_333_333, 33_333_333)),
            .dropped(hostNs: host + 100_000_000, count: 2, intervalMs: 66.66666666666667, reason: .backpressure),
            .dropped(hostNs: host + 133_000_000, count: 1, intervalMs: 33.333333333333336, reason: .encoder),
            .geometry(hostNs: host + 150_000_000, boundsPt: Rect(x: 3600, y: 0, width: 640, height: 360), scale: 2, dpi: 144),
            .failed(.windowHidden), .failed(.windowMinimized), .failed(.targetExited), .failed(.permissionRevoked),
            .failed(.diskFull), .failed(.maskGeometryUnknown), .failed(.helperLost),
            .failed(.protocolViolation("bad frame")), .failed(.io("disk")), .exited,
        ]
        var expected: [[String: Any]] = events.map(Messages.event)
        expected.append(Messages.response(id: 1, result: Messages.identity(
            osBuild: "27.0.1", helperIdentity: "rightkit-record-fake", signed: false, permission: .granted)))
        expected.append(Messages.response(id: 2, sources: [SourceInfo(
            windowId: 4242, pid: 77, appId: "dev.rightkit.fixture", title: "Fixture \"one\"",
            boundsPt: Rect(x: 3600, y: 0, width: 480, height: 270), visibility: .offScreenVisible)]))
        expected.append(Messages.response(id: 3, result: Messages.startInfo(StartInfo(
            hostNsAtStart: 1_000_000_000, width: 1600, height: 900, scale: 2.0,
            boundsPt: Rect(x: -10_000, y: -10_000, width: 800, height: 520), dpi: 144,
            codec: "hevc", osBuild: "27.0.1", visibility: .offScreenVisible))))
        expected.append(Messages.response(id: 4, result: Messages.finished(Finished(clean: true))))
        expected.append(Messages.bye)
        let actual = try XCTUnwrap(scenarios[0]["helperFrames"] as? [[String: Any]])
        XCTAssertEqual(actual.count, expected.count)
        for (mine, theirs) in zip(expected, actual) { same(mine, theirs) }

        // denied_and_unknown
        var second: [[String: Any]] = []
        second.append(Messages.response(id: 1, result: Messages.identity(
            osBuild: "27.0.1", helperIdentity: "rightkit-record-fake", signed: false, permission: .denied)))
        second.append(Messages.errorResponse(id: 2, .permissionDenied("not granted")))
        second.append(Messages.errorResponse(id: 3, .argInvalid("unknown operation Some(\"frobnicate\")")))
        second.append(Messages.response(id: 4, result: [:]))
        second.append(Messages.bye)
        let actual2 = try XCTUnwrap(scenarios[1]["helperFrames"] as? [[String: Any]])
        XCTAssertEqual(actual2.count, second.count)
        for (mine, theirs) in zip(second, actual2) { same(mine, theirs) }
    }

    func testIntegersStayIntegersOnTheWire() throws {
        // The core reads u64 fields with `as_u64`; a helper that writes 2.0 or 9.007e15 is refused.
        let host: UInt64 = 9_007_199_254_740_993
        let text = String(decoding: try Framing.json(Messages.event(.ready(
            FrameSample(index: 0, hostNs: host, samplePtsNs: 0, rawHash: "blake3:00")))), as: UTF8.self)
        XCTAssertTrue(text.contains("\"hostNs\":9007199254740993"), text)
        XCTAssertTrue(text.contains("\"index\":0"), text)
        let start = String(decoding: try Framing.json(Messages.startInfo(StartInfo(
            hostNsAtStart: 5, width: 640, height: 360, scale: 1, boundsPt: Rect(x: 0, y: 0, width: 1, height: 1),
            dpi: 72, codec: "h264", osBuild: "x", visibility: .offScreenVisible))), as: UTF8.self)
        XCTAssertTrue(start.contains("\"width\":640"), start)
        XCTAssertTrue(start.contains("\"dpi\":72"), start)
    }
}
